/* GTA VI Trophy Guide — projected fan guide (fresh rewrite)
   Neon Vice City dark theme, vanilla CSS. No frameworks. */

:root {
  --bg: #0d0716;
  --bg-raised: #171028;
  --bg-card: #1e1533;
  --border: #2f2247;
  --text: #ede7f6;
  --text-muted: #9a8fb8;
  --accent: #ff5fa2;      /* vice pink */
  --accent-2: #23d5d5;    /* vice teal */
  --accent-3: #ffc857;    /* sunset gold */
  --bronze: #cd8f5a;
  --silver: #c0c8d4;
  --gold: #ffd34d;
  --platinum: #7de8ff;
  --danger: #ff6b6b;
  --ok: #52e0a1;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.45);
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  line-height: 1.55;
}

a { color: var(--accent-2); }
.muted { color: var(--text-muted); font-size: 0.85em; }

/* ---------- Header ---------- */

.site-header {
  background: linear-gradient(160deg, #2a0f4d 0%, #12082a 55%, #0d0716 100%);
  border-bottom: 2px solid var(--border);
  color: #f4effc;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 20px 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
  align-items: center;
}

.site-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(255, 95, 162, 0.55);
}
.tagline { margin: 4px 0 0; color: #b9a9d8; font-size: 0.92rem; }

.header-controls { display: flex; gap: 10px; align-items: center; }

#spoiler-toggle {
  background: var(--bg-card);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 999px;
  padding: 9px 16px;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
}
#spoiler-toggle:hover { transform: translateY(-1px); box-shadow: 0 0 14px rgba(255, 95, 162, 0.4); }

.projection-banner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 10px 20px 16px;
  font-size: 0.88rem;
  color: var(--accent-3);
}

/* ---------- Spoiler banner ---------- */

.spoiler-banner {
  max-width: 1160px;
  margin: 14px auto 0;
  padding: 12px 16px;
  background: rgba(255, 95, 162, 0.12);
  border: 1px dashed var(--accent);
  border-radius: var(--radius);
  font-size: 0.9rem;
}

/* ---------- Layout ---------- */

.layout {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 20px;
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 24px;
  align-items: start;
}
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; }
}

/* ---------- Sidebar / filters ---------- */

.filters { position: sticky; top: 16px; display: grid; gap: 14px; }
@media (max-width: 900px) { .filters { position: static; } }

.filter-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
  box-shadow: var(--shadow);
}
.filter-card h2 {
  margin: 0 0 10px;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

#search-input {
  width: 100%;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg-raised);
  color: var(--text);
  font-size: 0.92rem;
}
#search-input:focus { outline: 2px solid var(--accent-2); border-color: var(--accent-2); }

.toggle-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  font-size: 0.88rem;
  color: var(--text-muted);
  cursor: pointer;
}
.toggle-row input { accent-color: var(--accent); }

.filter-row { display: flex; flex-wrap: wrap; gap: 7px; }

.filter-btn {
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-raised);
  color: var(--text-muted);
  font-size: 0.82rem;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.filter-btn:hover { border-color: var(--accent-2); }
.filter-btn.active {
  background: var(--accent-2);
  border-color: var(--accent-2);
  color: #08131a;
  font-weight: 600;
}

#sort-select {
  width: 100%;
  background: var(--bg-raised);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 7px 10px;
}

.progress-block { display: grid; gap: 8px; }
.progress-bar {
  height: 10px;
  border-radius: 999px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent-2), var(--accent));
  transition: width 0.3s;
}
.progress-text { margin: 0; font-size: 0.88rem; }

.btn {
  border: 1px solid var(--accent-2);
  background: transparent;
  color: var(--accent-2);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 0.82rem;
  cursor: pointer;
}
.btn:hover { background: var(--accent-2); color: #08131a; }
.btn.ghost { border-color: var(--border); color: var(--text-muted); }
.btn.ghost:hover { color: var(--danger); border-color: var(--danger); background: transparent; }

/* ---------- Trophy cards ---------- */

